use super::*;
#[test] fn test_result_references_reject_foreign_message(){let c=Connection::open_in_memory().unwrap();c.execute_batch("CREATE TABLE message(id INTEGER,conversation_id INTEGER);CREATE TABLE message_attachment(id INTEGER,message_id INTEGER,attachment_url TEXT);INSERT INTO message VALUES(1,10),(2,20);INSERT INTO message_attachment VALUES(3,1,'file.txt'),(4,2,'secret.txt')").unwrap();let(e,a)=result_references(&c,10,Some(2)).unwrap();assert!(e.is_empty());assert_eq!(a.len(),1);assert_eq!(a[0]["location"],"file.txt");let(e,_)=result_references(&c,10,Some(1)).unwrap();assert_eq!(e[0]["message_id"],1);}
